```json
{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE span_name LIKE '%ProductCatalogService/%' GROUP BY ALL ORDER BY 1,2,3",
          "claim": "In the abnormal window every ProductCatalog call from frontend, checkout and recommendation is an Error span, and product-catalog emits no spans of its own."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),2) AS avg_v, round(max(value),2) AS max_v, count(*) AS n FROM abnormal_metrics_sum WHERE attr_k8s_pod_name LIKE 'product-catalog%' AND metric='container.cpu.time' GROUP BY ALL",
          "claim": "product-catalog container CPU time is flat at zero throughout the abnormal window, versus about 2.3 average in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, min(value) AS min_uptime, max(value) AS max_uptime FROM abnormal_metrics_sum WHERE attr_k8s_pod_name LIKE 'product-catalog%' AND metric='k8s.pod.uptime' GROUP BY ALL",
          "claim": "product-catalog pod uptime rises continuously across the abnormal window with no reset, so the pod did not restart and stays gone."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='recommendation' AND attr_span_kind IN ('Client','Server') GROUP BY ALL",
          "claim": "All 37 recommendation calls to ProductCatalog ListProducts fail, and recommendation Client spans show Error status."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE span_name='grpc.oteldemo.ProductCatalogService/GetProduct' GROUP BY ALL",
          "claim": "169 frontend GetProduct calls to product-catalog error out in about 0.4 ms, against 47 successful calls in normal."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='checkout' GROUP BY ALL ORDER BY 1,2",
          "claim": "Checkout GetProduct client calls error, and every checkout PlaceOrder server span fails, so the order flow breaks at the product lookup."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE span_name IN ('grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY ALL",
          "claim": "Frontend PlaceOrder client calls and POST /api/checkout server spans return errors with HTTP 500."
        }
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE span_name IN ('grpc.oteldemo.RecommendationService/ListRecommendations','GET /api/recommendations') GROUP BY ALL",
          "claim": "Frontend ListRecommendations client calls and GET /api/recommendations server spans fail with HTTP 500 in the abnormal window."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns 500 for about 239 requests, matching frontend's failed server spans; user-facing requests fail."
        }
      ]
    }
  ]
}
